# Address of the 0.9999f float constant of the stumble test
# (ActCrowd::exec: `getRand(1.0f) >= 0.9999f`), in .sdata2, per version.
# "item" mode of Disable Pikmin Trip: when the item is received, the client writes
# 2.0f here. getRand(1.0f) returns [0,1[ so the condition is never true -> no
# more trips. This is DATA (not code): Dolphin's JIT rereads it on every
# execution, unlike a hot code rewrite which has no effect.
# This copy of 0.9999 is used ONLY by the trip test (the other 0.9999 tests in
# the game use other .sdata2 copies). PAL verified on the ISO; NTSC
# derived from the decomp (see below).
SYM_TRIP_RAND_CONST = {
    b"GPIP01": 0x803EE264,
    # NTSC: same constant @2356 of aiCrowd.cpp. The .sdata2 of aiCrowd has an
    # identical layout in both versions (decomp config/*/symbols.txt:
    # PAL 0x803EE230 + 0x34, NTSC 0x803E9310 + 0x34).
    b"GPIE01": 0x803E9344,
}
TRIP_DISABLED_FLOAT = 2.0  # written in place of 0.9999 to cancel the trip
TRIP_NORMAL_FLOAT = 0.9999  # original game value
TRIP_FORCED_FLOAT = 0.0     # Trip Trap: first test always true -> ~30 % per test

