# PlayerState.mContainerFlag (offset 0x184): byte 00 yyy xxx.
#   x (bits 0..2) = hasContainer(color): the onion is owned and follows between zones.
#       bit = 1 << colorIndex (Blue=0, Red=1, Yellow=2).
#   y (bits 3..5) = hasBootContainer(color): the onion is "started" (active).
#       bit = 1 << (colorIndex + 3).
# Skipping the discovery cutscene deprives the game of these updates, so we
# reproduce them (boot to activate, container for tracking across days/zones).
CONTAINER_COLOR_BIT = {"blue": 0x01, "red": 0x02, "yellow": 0x04}  # hasContainer (x)
CONTAINER_BOOT_ALL = 0x38  # all hasBootContainer (y) bits, bits 3/4/5

