# Offsets in the PlayerState struct (include/PlayerState.h)
PLAYERSTATE_OFFSETS = {
    # int mSproutedNum (_00) = "total sprouts"; TimeGraph mPerHourGraph
    # (_18C: u16 mStartTime, u16 mEndTime, PikiNum* mEntries @+4, PikiNum =
    # int[3] Blue/Red/Yellow) = end-of-day population graph.
    "mSproutedNum": 0x00,
    "mPerHourGraph": 0x18C,
    "mShipEffectPartFlag": 0x11,
    "mTotalRegisteredParts": 0x170,
    "mTotalParts": 0x174,
    "mCurrParts": 0x17C,
    "mRequiredUfoPartCount": 0x180,
    "mContainerFlag": 0x184,
    # Visual stage of the S.S. Dolphin (0=broken, 1..4=intermediate stages,
    # 5=PERFECT/repaired). Distinct from mCurrParts: the game only updates it
    # in PlayerState::registerPart(), never recomputes it automatically
    # from the part count -- so we must write it ourselves.
    "mShipUpgradeLevel": 0x10,
    # PlayerState.mDemoFlags (_54) is a DemoFlags; its mStoredFlags field (_08)
    # is a pointer to u8[32] (bitset of already seen cutscenes, indexed by
    # EDemoFlags). Offset of the POINTER in PlayerState: 0x54 + 0x08 = 0x5C.
    # Setting a bit = the matching cutscene no longer plays (the game sees
    # isFlag()==true). include/Demo.h + include/PlayerState.h.
    "mDemoFlagsStoredPtr": 0x5C,
    # bool PlayerState.mIsTutorialMode (_185, include/PlayerState.h). isTutorial()
    # returns it as is. TRUE => special day 1: crash intro (DEMOID_OlimarWakeUp),
    # frozen clock and tutorial pop-ups. Forcing it to 0 gives a regular day 1.
    "mIsTutorialMode": 0x185,
    "mStagePartsCollected": 0x187,
    # u8 PlayerState.mDisplayPikiFlag (_1AC): bit (1<<color) for each color whose
    # Pikmin counter is displayed (HUD, world map, end-of-day summary).
    # Set by setDisplayPikiCount(). Skipping the onion discovery leaves it at 0
    # for blue/yellow, which would hide owned onions in the menus.
    "mDisplayPikiFlag": 0x1AC,
    "mLivingPikiNum": 0x1A8,
    "mPartsCollectedByDay": 0x18,
}

